"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[[12,18],[16,24],[20,30]],[[8,12],[15,25],[24,36]],[[10,14],[18,27],[12,20]],[[16,24],[20,30],[12,18]],[[15,25],[24,36],[8,12]],[[18,27],[12,20],[10,14]]];
let variant=OrionProgress.variant('caravan'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,length=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
function gcd(a,b){while(b){const c=a%b;a=b;b=c;}return a;}
function setLength(n){if(solved||!Number.isInteger(n)||n<1||n>12)return;length=n;state='ready';render();}
function resetTrial(){length=1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('caravan')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(length!==gcd(...challenge()))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('sharing');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const [a,b]=challenge();return `<svg viewBox="0 0 360 260" role="img" aria-label="${t(`${length} ${length===1?'pack':'packs'}. Each has ${Math.floor(a/length)} red diamonds and ${Math.floor(b/length)} blue circles. Left over: ${a%length} red, ${b%length} blue.`,`${length} 包，每包 ${Math.floor(a/length)} 顆紅菱形、${Math.floor(b/length)} 顆藍圓形。剩餘：紅 ${a%length}、藍 ${b%length}。`)}">${Array.from({length},(_,i)=>{const x=8+(i%4)*87,y=8+Math.floor(i/4)*73;return `<g transform="translate(${x},${y})"><rect width="79" height="65" rx="8" fill="#29434b" stroke="#d7bb7d"/><text x="39" y="17" fill="#eed6a0" text-anchor="middle" font-size="12">#${i+1}</text><path d="M10 27L15 22L20 27L15 32Z" fill="#ff9b94"/><text x="25" y="31" fill="#fff" font-size="15">× ${Math.floor(a/length)}</text><circle cx="15" cy="48" r="5" fill="#87d4ff"/><text x="25" y="53" fill="#fff" font-size="15">× ${Math.floor(b/length)}</text></g>`;}).join('')}<text x="180" y="248" fill="#ffe3a0" text-anchor="middle" font-size="14">${t('Left over','剩餘')}: ◆ ${a%length} · ● ${b%length}</text></svg>`;}
function hints(){const [a,b]=challenge(),g=gcd(a,b);return[t('Watch the leftovers as you change the number of packs. Both colours must divide exactly.','改變包數，觀察剩餘寶石。兩種顏色都要剛好分完。'),t('A number that divides both totals is a common factor. Can you find a larger one?','能把兩個總數都整除的數是公因數。能找到更大的嗎？'),t(`Try ${g} packs: each gets ${a/g} red and ${b/g} blue, with none left over.`,`試試 ${g} 包：每包 ${a/g} 顆紅寶石、${b/g} 顆藍寶石，沒有剩餘。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Gem Caravans · Orion','寶石商隊 · Orion');$('stageTitle').textContent=t(`Delivery ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次運送 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Caravan seals · ${p} / 3`,`商隊封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('length').value=length;$('length').disabled=solved;$('lengthValue').textContent=String(length);$('length').setAttribute('aria-valuetext',t(`${length} ${length===1?'pack':'packs'}`,`${length} 包`));
$('goal').textContent=t(`${q[0]} red diamonds and ${q[1]} blue circles. Make the greatest number of identical packs, with no gems left over.`,`${q[0]} 顆紅菱形和 ${q[1]} 顆藍圓形。分成最多包完全相同的寶石包，不可有剩餘。`);$('reading').textContent=t(`Each pack: ${Math.floor(q[0]/length)} red + ${Math.floor(q[1]/length)} blue. Left over: ${q[0]%length} red + ${q[1]%length} blue.`,`每包：紅 ${Math.floor(q[0]/length)} + 藍 ${Math.floor(q[1]/length)}。剩餘：紅 ${q[0]%length} + 藍 ${q[1]%length}。`);$('reference').textContent=t('◆ Red diamonds · ● Blue circles','◆ 紅菱形 · ● 藍圓形');const messages={ready:['Change the pack count and inspect the shares.','改變包數，觀察每包的寶石。'],wrong:[q[0]%length||q[1]%length?'Some gems are left over. Try a different pack count.':'These packs match, but you can make MORE identical packs.',q[0]%length||q[1]%length?'有寶石剩餘，試試另一個包數。':'每包相同，但還可以分成更多包。'],success:['The greatest number of identical packs! The caravan is ready.','已分成最多包相同的寶石包，商隊準備好了！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('sharing')?t('Sharing Sigil saved in your collection.','均分符印已存入收藏。'):'';}
$('length').oninput=e=>setLength(Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('caravan',variant);observedVariant=OrionProgress.variant('caravan');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('sharing');render();};function syncProgress(){const v=OrionProgress.variant('caravan'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('sharing')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
